package com.wizzadrds.theworldremembers; import com.wizzadrds.theworldremembers.voice.*; import net.fabricmc.fabric.api.gametest.v1.GameTest; import net.minecraft.gametest.framework.GameTestHelper; import java.util.UUID; public final class VoiceSchedulerGameTest { @GameTest public void directVoicePreemptsAmbient(GameTestHelper c){var s=new VoiceScheduler(1);s.submit(new VoiceJob(UUID.randomUUID(),"ambient",VoicePriority.AMBIENT,1));s.submit(new VoiceJob(UUID.randomUUID(),"direct",VoicePriority.DIRECT,2));var j=s.startNext();if(j==null||j.priority()!=VoicePriority.DIRECT){c.fail("Direct voice did not preempt ambient");return;}c.succeed();} }
